@startuml

class Aircraft {
  + name : string
  + type : string
  + yearOfManufacture : int
  + nextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + numberOfSeats : int
}

class SeatCategory {
  + designation : string
  + offersEntertainment : boolean
  + numberOfSeats : int
}

class Flight {
  + flightNumber : string
  + date : date
}

class Passenger {
  + name : string
  + passportNumber : string
}

class Ticket {
  + ticketNumber : string
  + price : float
  + upgradeDesired : boolean
}

class Airline {
  + name : string
}

abstract class AirlineEmployee {
  + name : string
  + employmentDate : date
}

class FlightAttendant extends AirlineEmployee {
  + isChiefStewardess : boolean
}

class Pilot extends AirlineEmployee {
  + license : string
}

class Airport {
  + name : string
  + address : string
  + numberOfRunways : int
}

Airline "1" -- "*" Aircraft : owns
Airline "1" -- "*" AirlineEmployee : employs
Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs

PassengerAircraft "1" *-- "*" SeatCategory : has
PassengerAircraft "1" -- "*" Flight : performs
Flight "1" -- "*" Ticket : contains
Passenger "1" -- "*" Ticket : holds
Ticket "*" -- "1" SeatCategory : for

Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Aircraft "0..1" -- "1" Airport : home airport at

Flight "1" -- "1..*" FlightAttendant : staffed by
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1..2" Pilot : co-pilot

@enduml

